insert into public.topics (module_id, slug, title, summary, position, published) select id, 'final-portfolio-project', 'Final Portfolio Project', 'A production-minded full-stack portfolio project demonstrating everything learned.', 0, true from public.modules where level_id = 3 and title = 'Final Project' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain final portfolio project in your own words.","Recognise and apply: a portfolio project must solve a real problem and be deployed live.","Recognise and apply: document the stack, the data model, the security rules and how to run it.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers final portfolio project: a production-minded full-stack portfolio project demonstrating everything learned. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that a portfolio project must solve a real problem and be deployed live. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that document the stack, the data model, the security rules and how to run it. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how final portfolio project fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'markdown', '# Final Portfolio Project
